head.script:
scwin.onpageload = function() {
    var jsonData = [{
        "col1": "col1",
        "col2": "col2",
        "col3": "col3",
        "col4": "0"
    }, {
        "col1": "col4",
        "col2": "col5",
        "col3": "col6",
        "col4": "0"
    }, {
        "col1": "col7",
        "col2": "col8",
        "col3": "col9",
        "col4": "0"
    }, {
        "col1": "col10",
        "col2": "col12",
        "col3": "col13",
        "col4": "0"
    }]
    dataList1.setJSON(jsonData);
};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function() {
    debugger;
    var cellInfo = gridView1.getCellInfo(1);
    if (cellInfo.options.blockSelect === true) {
        gridView1.setBlockSelect(1, false);
    } else {
        gridView1.setBlockSelect(1, true);
    }
}
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#gridView1_cell_0_0', 'drag-n-drop', {
        dx: 1600,
        dy: 0
    });
}
scwin.setSimulate2 = function() {
    scwin.simulateWrapper('#tac_main_contents_content1_body_popupundefined_header', 'drag-n-drop', {
        dx: -50,
        dy: 0
    });
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_cell_0_0').click()");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('#tac_main_contents_content1_body').scrollLeft('300')");
    WebSquare.wUnit.addCommand("pause", "400");
    //WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
    WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#tac_main_contents_content1_body').scrollLeft() > 0", "true");
    WebSquare.wUnit.addCommand("pause", "400");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
